/*
-----------------------------------------------
Blogger Template Style
Name:        Sport Live 24 - سبورت لايف 24
Version:     2.0.0
Developer:   ساجد العبادلة - https://github.com/Dev-saged
Base:        Telewix Sports free (CC BY 3.0)
Last Update: 12/November/2026
----------------------------------------------- */
/*
<!-- Variable definitions -->
    <Group description="Theme Colors" selector="body">
    <Variable name="body.background" description="Theme Background Color" type="background" color="#f3f8ff" default="#f3f8ff url() repeat fixed top left" value="#f3f8ff url() repeat fixed top left"/>
    <Variable name="main.text.color" description="Theme Main Text Color" type="color" default="#101010" value="#101010"/>
    <Variable name="main.link.color" description="Theme Main Link Color" type="color" default="#112b3e" value="#112b3e"/>
    <Variable name="keycolor" description="Mobile Address Bar Color" type="color" default="#4E65FF" value="#4E65FF"/>
    <Variable name="main.button.color" description="Main Buttons Colors" type="color" default="#4E65FF" value="#4E65FF"/>
    <Variable name="main.button.text.color" description="Main Buttons Text Color" type="color" default="#ffffff" value="#ffffff"/>
    <Variable name="text.post.inner" description="Posts Article Text Color" type="color" default="#505050" value="#505050"/>
    <Variable name="theme.text.color" description="Theme Text Color" type="color" default="#3e3e3e"  value="#3e3e3e"/>
    </Group>
    <Group description="Top Bar Colors" selector="nav#top-bar">
    <Variable name="top.bar" description="Top Menu Background" type="color" default="#ffffff" value="#ffffff"/>
    <Variable name="top.bar.menufont" description="Top Menu Title Color" type="color" default="#333333" value="#333333"/>
    </Group>
    <Group description="Main Menu Colors" selector="div.Super-MenuWorks">
    <Variable name="main.menu.bg" description="Main Menu Background 0" type="color" default="#ffffff" value="#ffffff"/>
    <Variable name="main.menu.text.color" description="Main Menu Text Color" type="color" default="#000000" value="#000000"/>
    <Variable name="submenu.background.color" description="SubMenu Background Color" type="color" default="#ffffff" value="#ffffff"/>
    <Variable name="sub.menu.text.color" description="SubMenu Text Color" type="color" default="#1f2937" value="#1f2937"/>
    <Variable name="main.logo.text.color" description="Main Logo Text Color" type="color" default="#222222" value="#222222"/>
    </Group>
    <Group description="Mobile Menu Colors" selector="div.Super-MenuWorks">
    <Variable name="mobile.menu.bg.color" description="Mobile Menu Background Color" type="color" default="#ffffff" value="#ffffff"/>
    </Group>
    <Group description="Featured Gadgets Colors" selector="#feed-view">
    <Variable name="featured.gadgets.title" description="Featured Gadgets Title" type="color" default="#e8e8e8"  value="#e8e8e8"/>
    <Variable name="featured.posts.title" description="Featured Posts Title" type="color" default="#333333"  value="#333333"/>
    <Variable name="lables.buttons.color" description="Lables Buttons Color" type="color" default="#4E65FF"  value="#4E65FF"/>
    <Variable name="lables.text.color" description="Lables Buttons Text Color" type="color" default="#ffffff"  value="#ffffff"/>
    </Group>
    <Group description="Sidebar Colors" selector="div.sidebar">
    <Variable name="cloud.bg.color" description="Cloud Labels Color" type="color" default="#4E65FF"  value="#4E65FF"/>
    <Variable name="list.text.color" description="List Labels Color" type="color" default="#333333"  value="#333333"/>
    <Variable name="email.bg.color" description="Email Subscription Color" type="color" default="#4E65FF"  value="#4E65FF"/>
    <Variable name="email.text.color" description="Email Subscription Text Color" type="color" default="#ffffff"  value="#ffffff"/>
    </Group>
    <Group description="Footer Colors" selector="div#bnfg-gx3s3">
    <Variable name="footer.background.color" description="Footer Background  Color" type="color" default="#141629" value="#141629"/>
    <Variable name="footer.gadgets.title" description="Footer Gadget Title Color" type="color" default="#e8e8e8" value="#e8e8e8"/>
    <Variable name="footer.title.color" description="Footer Title Color" type="color" default="#e8e8e8" value="#e8e8e8"/>
    <Variable name="footer.about.color" description="Footer About Us Color" type="color" default="#868686" value="#868686"/>
    <Variable name="footer.text.color" description="Footer Text Color" type="color" default="#d7d7d7" value="#d7d7d7"/>
    <Variable name="footer.copyright.bg" description="Footer Copyright Background Color" type="color" default="#101121" value="#101121"/>
    </Group>
    <Group description="Theme Fonts" selector="body">
    <Variable name="main.font" description="Site Font" type="font" family="Noto Kufi Arabic" default="normal 400 14px $(family)"  value="normal 400 14px $(family)"/>
    <Variable name="title.font" description="Title Font" type="font" family="Noto Kufi Arabic" default="normal 400 14px $(family)"  value="normal 400 14px $(family)"/>
    <Variable name="meta.font" description="Meta Font" type="font" family="Noto Kufi Arabic" default="normal 400 14px $(family)"  value="normal 400 14px $(family)"/>
    <Variable name="text.font" description="Text Font" type="font" family="Noto Kufi Arabic" default="normal 400 14px $(family)"  value="normal 400 14px $(family)"/>
    </Group>
    <Group description="Theme Widths" selector="body">
    <Variable name="outerContainer.width" description="Container Width" type="length" default="1178px" min="1178px" max="1378px" value="1178px"/>
    <Variable name="sidebar.width" description="Sidebar Width" type="length" default="320px" min="300px" max="336px" value="320px"/>
    </Group>
    <Group description="Reset (All Theme Fonts)">
    <!-- Site Font -->
    <Variable name="mainfont.normal" description="Main Font Normal" type="font" default="normal 500 14px $(main.font.family)" value="normal 500 14px $(family)"/>
    <Variable name="mainfont.italic" description="Main Font Italic" type="font" default="italic 400 14px $(main.font.family)" value="italic 400 14px $(family)"/>
    <Variable name="mainfont.semibold" description="Main Font SemiBold" type="font" default="normal 600 14px $(main.font.family)" value="normal 600 14px $(family)"/>
    <Variable name="mainfont.semibolditalic" description="Main Font SemiBold Italic" type="font" default="italic 600 14px $(main.font.family)" value="italic 600 14px $(family)"/>
    <Variable name="mainfont.bold" description="Main Font Bold" type="font" default="normal 700 14px $(main.font.family)" value="normal 700 14px $(family)"/>
    <Variable name="mainfont.bolditalic" description="Main Font Bold Italic" type="font" default="italic 700 14px $(main.font.family)" value="italic 700 14px $(family)"/>
    <!-- Title Font -->
    <Variable name="titlefont.italic" description="Title Font Italic" type="font" default="italic 400 14px $(title.font.family)" value="italic 400 14px $(family)"/>
    <Variable name="titlefont.normal" description="Title Font Normal" type="font" default="normal 500 14px $(title.font.family)" value="normal 500 14px $(family)"/>
    <Variable name="titlefont.normalitalic" description="Title Font Normal Italic" type="font" default="italic 500 14px $(title.font.family)" value="italic 500 14px $(family)"/>
    <Variable name="titlefont.semibold" description="Title Font SemiBold" type="font" default="normal 600 14px $(title.font.family)" value="normal 600 14px $(family)"/>
    <Variable name="titlefont.semibolditalic" description="Title Font SemiBold Italic" type="font" default="italic 600 14px $(title.font.family)" value="italic 600 14px $(family)"/>
    <Variable name="titlefont.bold" description="Title Font Bold" type="font" default="normal 700 14px $(title.font.family)" value="normal 700 14px $(family)"/>
    <Variable name="titlefont.bolditalic" description="Title Font Bold Italic" type="font" default="italic 700 14px $(title.font.family)" value="italic 700 14px $(family)"/>
    <!-- Meta Font -->
    <Variable name="metafont.italic" description="Meta Font Italic" type="font" default="italic 400 14px $(meta.font.family)" value="italic 400 14px $(family)"/>
    <Variable name="metafont.normal" description="Meta Font Normal" type="font" default="normal 500 14px $(meta.font.family)" value="normal 500 14px $(family)"/>
    <Variable name="metafont.normalitalic" description="Meta Font Normal Italic" type="font" default="italic 500 14px $(meta.font.family)" value="italic 500 14px $(family)"/>
    <!-- Text Font -->
    <Variable name="textfont.italic" description="Text Font Italic" type="font" default="italic 400 14px $(text.font.family)" value="italic 400 14px $(family)"/>
    <Variable name="textfont.normal" description="Text Font Normal" type="font" default="normal 500 14px $(text.font.family)" value="normal 500 14px $(family)"/>
    <Variable name="textfont.normalitalic" description="Text Font Normal Italic" type="font" default="italic 500 14px $(text.font.family)" value="italic 500 14px $(family)"/>
    <Variable name="textfont.semibold" description="Text Font SemiBold" type="font" default="normal 600 14px $(text.font.family)" value="normal 600 14px $(family)"/>
    <Variable name="textfont.semibolditalic" description="Text Font SemiBold Italic" type="font" default="italic 600 14px $(text.font.family)" value="italic 600 14px $(family)"/>
    <Variable name="textfont.bold" description="Text Font Bold" type="font" default="normal 700 14px $(text.font.family)" value="normal 700 14px $(family)"/>
    <Variable name="textfont.bolditalic" description="Text Font Bold Italic" type="font" default="italic 700 14px $(text.font.family)" value="italic 700 14px $(family)"/>
    </Group>
			<!-- Extra Variables -->
    <Variable name="body.background.color" description="Body Background Color" type="color" default="transparent"  value="transparent"/>
    <Variable name="body.post.color" description="Body Post Color" hideEditor="true" type="color" default="#ffffff"  value="#ffffff"/>
	<Variable name="body.text.font" description="Font" hideEditor="true" type="font" default="13px arial, sans-serif"  value="13px arial, sans-serif"/>
	<Variable name="body.text.color" description="Body Text Color" hideEditor="true" type="color" default="#6d6d6d"  value="#6d6d6d"/>
    <Variable name="body.title.color" description="Comments Color" hideEditor="true" type="color" default="#1f2937" value="#1f2937"/>
    <Variable name="body.link.color" description="Body Link Color" hideEditor="true" type="color" default="#6d6d6d"  value="#6d6d6d"/>
    <Variable name="body.action.font.large" description="Comments Font 2" hideEditor="true" type="font" default="normal 700 14px Arial, sans-serif !important"  value="normal 700 14px, Arial, sans-serif !important"/>
*/
/*-- Noto Kufi Arabic (variable 400-800) --*/
@font-face{font-family:'Noto Kufi Arabic';font-style:normal;font-weight:400 800;font-display:swap;src:url(https://fonts.gstatic.com/s/notokufiarabic/v27/CSRk4ydQnPyaDxEXLFF6LZVLKrodrOYFFlKp.woff2) format('woff2');unicode-range:U+0600-06FF,U+0750-077F,U+0870-0891,U+0897-08E1,U+08E3-08FF,U+200C-200E,U+2010-2011,U+204F,U+2E41,U+FB50-FDFF,U+FE70-FE74,U+FE76-FEFC}
@font-face{font-family:'Noto Kufi Arabic';font-style:normal;font-weight:400 800;font-display:swap;src:url(https://fonts.gstatic.com/s/notokufiarabic/v27/CSRk4ydQnPyaDxEXLFF6LZVLKrodrOMFFg.woff2) format('woff2');unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}
/*-- Font Awesome Free 5.15.4 --*/
@font-face{font-family:"Font Awesome 5 Brands";font-display:swap;font-style:normal;font-weight:400;src:url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-brands-400.woff2) format("woff2"),url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-brands-400.woff) format("woff")}.fab{font-family:"Font Awesome 5 Brands";font-weight:400}
@font-face{font-family:"Font Awesome 5 Free";font-display:swap;font-style:normal;font-weight:400;src:url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-regular-400.woff2) format("woff2"),url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-regular-400.woff) format("woff")}.far{font-family:"Font Awesome 5 Free";font-weight:400}
@font-face{font-family:"Font Awesome 5 Free";font-display:swap;font-style:normal;font-weight:900;src:url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-solid-900.woff2) format("woff2"),url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-solid-900.woff) format("woff")}.fa,.far,.fas{font-family:"Font Awesome 5 Free"}.fa,.fas{font-weight:900}
/*-- Reset CSS Start Here --*/

:root{
--body-font:'$(main.font.family)', Arial, sans-serif;
--title-font:'$(title.font.family)', Arial, sans-serif;
--meta-font:'$(meta.font.family)', Arial, sans-serif;
--text-font:'$(text.font.family)', Arial, sans-serif;
--text-font-color:$(text.post.inner);
--runs-solid-color:#c1bbbb;
--black-color:#404040;
--hero-color:#aaaaaa;
--main-menu-bg:$(main.menu.bg);
--snippet-color:#aba4a4;
--solid-border:#ddd;
--top-bar:$(top.bar);
--featured-posts-title:$(featured.posts.title);
--button-bg-color:$(main.button.color);
--button-text-color:$(main.button.text.color);
