a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{padding:0;border:0;outline:0;vertical-align:baseline;background:0;text-decoration:none}
form,textarea,input,button{font-family:var(--body-font);-webkit-appearance:none;-moz-appearance:none;appearance:none;border-radius:0;box-sizing:border-box}
.CSS_LIGHTBOX{z-index:999999!important}.CSS_LIGHTBOX_ATTRIBUTION_INDEX_CONTAINER .CSS_HCONT_CHILDREN_HOLDER > .CSS_LAYOUT_COMPONENT.CSS_HCONT_CHILD:first-child > .CSS_LAYOUT_COMPONENT{opacity:0}
input,textarea{outline:none}
/*! normalize.css v3.0.1 | MIT License | git.io/normalize */
dl,ul{list-style-position:inside;font-weight:400;list-style:none}
ul li{list-style:none}
caption,th{text-align:center}
html,body{text-size-adjust:none;-webkit-text-size-adjust:none;-moz-text-size-adjust:none;-ms-text-size-adjust:none}
.separator a{clear:none!important;float:none!important;margin-left:0!important;margin-right:0!important}
#Navbar1,#navbar-iframe,.widget-item-control,a.quickedit,.home-link,.feed-links{display:none!important}
.center{display:table;margin:0 auto;position:relative}
.widget > h2,.widget > h3{display:none}
.widget iframe,.widget img{max-width:100%}
.container{position:relative;max-width: 100%;width: 1145px;}
.center{display:table;margin:0 auto;position:relative}
img{border:0;position:relative}
a,a:visited{text-decoration:none}
.clearfix{clear:both}
.section,.widget,.widget ul{margin:0;padding:0}
a{color:var(--all-link-color)}
a img{border:0}
abbr{text-decoration:none}
.widget>h2,.widget>h3{display:none}
*:before,*:after{-webkit-box-sizing:border-box;-moz-box-sizing:border-box;box-sizing:border-box;}
/*-- CSS Variables --*/
.no-items.section{display:none}
h1,h2,h3,h4,h5,h6{font-family:var(--title-font);font-weight:600}
body{position:relative;background:var(--body-color-main);font-family:var(--body-font);font-size:14px;font-weight:400;color:var(--black-text);word-wrap:break-word;margin:0;padding:0;font-style:normal;line-height:1.4em}
#outer-wrapper{position:relative;overflow:hidden;width:100%;max-width:100%;margin:0 auto}
.outer-container{display: flex;justify-content: space-between;}
h1{font-size:26px;line-height:28px}
h3{font-size:22px;line-height:21px}
h4{font-size:20px;line-height:18px}
h5{font-size:16px;line-height:16px}
h6{font-size:13px;line-height:13px;margin-bottom:0;margin-top:0}
@media only screen and (min-width:1025px){h1{font-size:42px;line-height:46px}
h2{font-size:36px;line-height:40px}
h3{font-size:28px;line-height:35px}
h4{font-size:21px;line-height:26px}
}
.post-body h1{font-size:28px}
.post-body h2{font-size:24px}
.post-body h3{font-size:21px}
.post-body h4{font-size:18px}
.post-body h5{font-size:16px}
.post-body h6{font-size:13px}
.dark .post-body p{background:transparent!important;color:#fff!important}
.post-body pre{
display:block;
}
.post-body pre code{
position:relative;
display:block;
background:rgb(72 72 72 / 0.09);
font-family:Monospace;
font-size:14px;
color:var(--black-text);;
overflow-x: auto;
line-height:1.6em;
padding:15px;
border:0;
border-radius:4px;
text-align:left;
direction:ltr;
}
#center-container{position:relative;float:left;width:100%;overflow:hidden;padding:20px 0 0;margin:0}
#feed-view{position:relative;float:left;width:calc(100% - ($(sidebar.width) + 15px));box-sizing:border-box;padding:0}
#sidebar-container{position:relative;float:right;width:$(sidebar.width);box-sizing:border-box;padding:0}
.post-filter-image{position:relative;display:block;transition:transform .3s ease}
.snip-thumbnail{position:relative;width:100%;height:100%;display:block;object-fit:cover;z-index:1;opacity:0;transition:opacity .30s ease,transform .30s ease}
.snip-thumbnail.lazy-img{opacity:1}
.row,.row-1{position:relative;}
.post-filter-link:hover .snip-thumbnail{filter: brightness(0.9);}
.background-layer:before{content:'';position:absolute;left:0;right:0;bottom:0;height:66%;background-image:linear-gradient(to bottom,transparent,rgb(4 12 62));-webkit-backface-visibility:hidden;backface-visibility:hidden;z-index:2;opacity:1;margin:0;transition:opacity .25s ease}
.colorful-ico a:before,.social a:before{display:inline-block;font-family:'Font Awesome 5 Brands';font-style:normal;font-weight:400}
.colorful-ico .facebook a:before,.social .facebook:before{content:"\f09a"}
.colorful-ico .facebook-f a:before,.social .facebook-f:before{content:"\f09a"}
.colorful-ico .instagram a:before,.social .instagram:before{content:"\f16d"}
.colorful-ico .whatsapp a:before,.social .whatsapp:before{content:"\f232"}
.colorful-ico .telegram a:before,.social .telegram:before{content:"\f2c6"}
.colorful-ico .youtube a:before,.social .youtube:before{content:"\f167"}
.colorful-ico .github a:before,.social .github:before{content:"\f09b"}
.colorful-ico .rss a:before,.social .rss:before{content:'\f09e';font-family:'Font Awesome 5 Free';font-weight:900}
