/* سكربت القالب الأساسي — نسخة نظيفة مفكوكة (بدون تشفير أو سكربتات خارجية مجهولة) */
(function ($) {
  "use strict";
  var MONTHS = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
  var BLANK = "https://resources.blogblog.com/img/blank.gif";
  var FEED_TYPES = ["grid1", "block1", "video", "list1", "block2", "footer", "sidebar"];
  var WRAPS = {
    grid1: "erf3f-main-xxui8", block1: "xce4-main-xcgr5", video: "video-vg", list1: "center-main-wrapper",
    block2: "block-hall", sidebar: "BiggerSidebarOk", footer: "cvcx-cv", related: "BiggerRelated"
  };

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function feedUrl(label, max) {
    var u = "/feeds/posts/summary?alt=json&max-results=" + max;
    return label.indexOf("recent") === -1 ? u.replace("/summary?", "/summary/-/" + encodeURIComponent(label) + "?") : u;
  }
  function loadDiv() { return "<div class='loading-icon'></div>"; }
  function entryLink(e) {
    for (var i = 0; i < (e.link || []).length; i++) if (e.link[i].rel === "alternate") return e.link[i].href;
    return "#";
  }
  function entryPhoto(e) { return e.media$thumbnail ? e.media$thumbnail.url : BLANK; }
  function entrySum(e) { return e.summary ? e.summary.$t.substring(0, 150) : ""; }
  function entryLabel(e) { return e.category && e.category[0] ? e.category[0].term : "recent"; }
  function authorName(e) { return e.author && e.author[0] ? e.author[0].name.$t : ""; }
  function authorPhoto(e) {
    return e.author && e.author[0] && e.author[0].gd$image ? e.author[0].gd$image.src : BLANK;
  }
  function dateDiv(e) {
    var iso = e.published.$t, p = iso.split("T")[0].split("-");
    return "<span class='post-date' datetime='" + esc(iso) + "'>" + parseInt(p[2], 10) + " " + MONTHS[parseInt(p[1], 10) - 1] + " " + p[0] + "</span>";
  }

  function renderItem(type, d, total, x) {
    var img = "<img class='snip-thumbnail' alt='" + x.title + "' data-src='" + x.photo + "'>";
    var author = "<div class='post-snip'><img class='post-author-image' alt='" + x.author + "' src='" + x.authorPhoto + "'><span class='post-author'>" + x.author + "</span>" + x.date + "</div>";
    var title = "<h2 class='entry-title'><a href='" + x.url + "' title='" + x.title + "'>" + x.title + "</a></h2>";
    var tag = "<span class='post-tag'>" + x.label + "</span>";
    var dateOnly = "<div class='post-snip'>" + x.date + "</div>";
    var open = d === 1, close = d === total - 1 ? "</div>" : "";
    switch (type) {
      case "grid1":
        return "<div class='cvxc-gribv'><div class='modal-image'><a class='post-filter-inner' href='" + x.url + "'><span class='post-filter-link background-layer image-nos'>" + img + "</span></a><div class='entery-category-fly'>" + tag + title + author + "</div></div></div>";
      case "block1":
        if (d === 0) return "<div class='xcxxc-secon fl item0'><div class='block-img'><a class='post-filter-link background-layer image-nos' href='" + x.url + "'>" + img + "</a><div class='entery-category-fly'>" + tag + title + author + "</div></div></div>";
        return (open ? "<div class='block-box fl'>" : "") + "<div class='cvbxc-scpc item" + d + "'><div class='entery-category-box'>" + title + dateOnly + "</div></div>" + close;
      case "video":
        if (d === 0) return "<div class='video-section vg-s item0'><div class='vblock-img'><a class='post-filter-link background-layer video-nos' href='" + x.url + "'>" + img + "</a><div class='entery-category-fly'>" + tag + title + author + "</div></div></div>";
        return (open ? "<div class='video-grid vg-s'>" : "") + "<div class='video-step item" + d + "'><div class='vblock-thumb'><a class='post-filter-link video-nos' href='" + x.url + "'>" + img + "</a></div><div class='entery-category-box'>" + title + dateOnly + "</div></div>" + close;
      case "list1":
        return "<div class='cv-flxcb'><div class='cv-flxcb-thumb'><a class='post-filter-link image-nos' href='" + x.url + "'>" + img + "</a></div><div class='entery-category-box'>" + tag + title + "<div class='post-snippet'>" + x.summary + "</div>" + author + "</div></div>";
      case "block2":
        if (d === 0) return "<div class='vdfgl-sectf rv item0'><div class='hall-img'><a class='post-filter-link background-layer image-nos' href='" + x.url + "'>" + img + "</a><div class='entery-category-fly'>" + tag + title + author + "</div></div></div>";
        return (open ? "<div class='hall-grid rv'>" : "") + "<div class='hall-step item" + d + "'><div class='hall-thumb'><a class='post-filter-link image-nos' href='" + x.url + "'>" + img + "</a><span class='post-tag-fly'>" + x.label + "</span></div><div class='entery-category-box'>" + title + dateOnly + "</div></div>" + close;
      case "sidebar":
        return "<div class='sidebarui-posts'><div class='glax-img'><a class='post-filter-link image-nos' href='" + x.url + "'>" + img + "</a></div><div class='entery-category-box'>" + title + dateOnly + "</div></div>";
      case "footer":
        return "<div class='footer-sector'><div class='footer-sector-thumb'><a class='post-filter-link image-nos' href='" + x.url + "'>" + img + "</a></div><div class='entery-category'>" + title + dateOnly + "</div></div>";
      case "related":
        return "<div class='recbvf-bbv'><div class='recbvf-bbv-thumb'><a class='post-filter-link image-nos' href='" + x.url + "'>" + img + "</a></div><div class='entery-category'>" + title + dateOnly + "</div></div>";
    }
    return "";
  }

  function feedEvent(box, type, label, max) {
    $.ajax({
      type: "get",
      url: feedUrl(label, max),
      dataType: "json",
      timeout: 15000,
      success: function (res) {
        var entries = (res.feed && res.feed.entry) || [], html = "";
        if (!entries.length) {
          box.html("<span class='error-status'>" + esc(window.pikiMessages && pikiMessages.noResults || "لا توجد مواضيع بعد") + "</span>");
          return;
        }
        for (var d = 0; d < entries.length; d++) {
          var e = entries[d];
          html += renderItem(type, d, entries.length, {
            title: esc(e.title.$t), url: esc(entryLink(e)), label: esc(entryLabel(e)), photo: esc(entryPhoto(e)),
            author: esc(authorName(e)), authorPhoto: esc(authorPhoto(e)), date: dateDiv(e), summary: esc(entrySum(e))
          });
        }
        box.html("<div class='" + WRAPS[type] + "'>" + html + "</div>");
      },
      error: function () {
        box.html("<span class='error-status'>تعذّر تحميل المواضيع حالياً، حاول تحديث الصفحة.</span>");
      },
      complete: function () { $(".snip-thumbnail:not(.lazy-img)").lazyimg(); }
    });
  }
  function trimSpaces(s) { return $.trim(s); }
  function extrbd(text, key) {
    var out = "", parts = String(text || "").split("#");
    for (var i = 0; i < parts.length; i++) {
      var k = key + "=(", at = parts[i].indexOf(k);
      if (at > -1) out = parts[i].substring(at + k.length, parts[i].indexOf(")"));
    }
    return out;
  }
  function whenVisible(el, fn) {
    var $w = $(window);
    function check() {
      if ($w.scrollTop() + $w.height() > el.offset().top) { $w.off("resize scroll load", check); fn(); }
    }
    $w.on("resize scroll load", check);
    check();
  }

  $("#Super-FlexMenu").each(function () { $(this).Menuiki(); });
  $(".show-menu-space").on("click", function () { $("body").addClass("spring-open"); });
  $(".hide-Super-Menu, .overlay").on("click", function () { $("body").removeClass("spring-open show-share"); });
  $(".mega-mode .dark-toggle").on("click", function () {
    var dark = !$("body").hasClass("dark");
    $("body").toggleClass("dark", dark);
    try { localStorage.setItem("mode", dark ? "darkmode" : "light"); } catch (e) {}
  });
  $("#Super-FlexMenuList").clone().appendTo("#Super-Menu");
  $(".flex-footer .colorful-ico").first().clone().appendTo("#menu-space .social-mobile");
  $("#Super-Menu").on("click", ".sub-tab > a", function () {
    $(this).parent().find(".m-sub").eq(0).slideToggle();
    return false;
  });
  $(".search-button-flex").on("click", function () {
    $("body").addClass("active-search");
    $("#search-flex").show().find(".search-input").trigger("focus");
  });
  $(".search-flex-close").on("click", function () {
    $("body").removeClass("active-search");
    $("#search-flex").fadeOut(200);
  });
  $(document).on("keydown", function (e) {
    if (e.key === "Escape") { $("body").removeClass("active-search spring-open show-share"); $("#search-flex").fadeOut(200); }
  });
  $(function () { $("#hot-posts").lazyticker(); });
  $(".snip-thumbnail:not(.lazy-img)").lazyimg();

  $(".HTML .widget-content").each(function () {
    var box = $(this), parts = box.text().split("/");
    if (parts.length !== 3 || FEED_TYPES.indexOf(trimSpaces(parts[1])) === -1) return;
    var num = trimSpaces(parts[0]), type = trimSpaces(parts[1]), label = trimSpaces(parts[2]);
    if (type !== "sidebar" && type !== "footer") {
      var more = label.indexOf("recent") > -1 ? "/search" : "/search/label/" + encodeURIComponent(label);
      box.parent().find(".widget-title").append("<a class='simple-viewmore' href='" + more + "'>عرض المزيد</a>");
    }
    box.html(loadDiv());
    whenVisible(box, function () { feedEvent(box, type, label, num); });
  });

  $(".share-top,.show-hid").on("click", function () { $("body").addClass("show-share"); });
  $(".close-check").on("click", function () { $("body").removeClass("show-share"); });
  $(".copy-post button").on("click", function () {
    var btn = $(this), wrap = btn.parent(), input = document.getElementById("showlink");
    function done() {
      btn.text("تم النسخ");
      wrap.addClass("copied");
      setTimeout(function () { btn.text("نسخ"); wrap.removeClass("copied"); }, 4000);
    }
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(input.value).then(done, function () { input.select(); document.execCommand("copy"); done(); });
    } else { input.select(); document.execCommand("copy"); done(); }
  });
  $(".share-wrapper-icons li .window-piki, .share-runs li .window-piki").on("click", function () {
    var b = $(this), w = +b.data("width") || 600, h = +b.data("height") || 500;
    var win = window.open(b.data("url"), "_blank", "noopener,scrollbars=yes,resizable=yes,width=" + w + ",height=" + h +
      ",left=" + Math.round(screen.width / 2 - w / 2) + ",top=" + Math.round(screen.height / 2 - h / 2));
    if (win) win.focus();
  });
  $(".Super-related").each(function () {
    var box = $(this), label = box.find(".related-tag").attr("label") || "recent";
    box.html(loadDiv());
    whenVisible(box, function () { feedEvent(box, "related", label, window.relatedPostsNum || 3); });
  });
  $("#show-comment-form").on("click", function () {
    $(".comment-form").show();
    $("#top-ce").show();
    $(this).hide();
  });
  $("#back-top").each(function () {
    var btn = $(this);
    $(window).on("scroll", function () { $(this).scrollTop() >= 100 ? btn.fadeIn(200) : btn.fadeOut(200); });
    btn.on("click", function () { $("html,body").animate({ scrollTop: 0 }, 500); });
  });
  $("#cookies-iki").each(function () {
    var box = $(this), title = box.find(".widget-title .title").html();
    var days = parseInt(extrbd(title, "days"), 10) || 20;
    box.find(".cookies-bt").text(extrbd(title, "buttons") || "أقبل");
    box.find(".cookies-bt").on("click", function () {
      box.removeClass("cookies-show");
      setTimeout(function () { box.hide(); }, 500);
      Cookies.set("cookiesMsg", "deja", { expires: days, path: "/" });
    });
    if (Cookies.get("cookiesMsg") !== "deja") setTimeout(function () { box.show().addClass("cookies-show"); }, 3000);
  });
  $("#upper-ad").each(function () { $(this).appendTo("#top-ad-placeholder"); });
  $("#lower-ad").each(function () { $(this).appendTo("#bottom-ad-placeholder"); });
  $("#feed-view, #sidebar-container").each(function () {
    if (typeof fixedSidebar === "undefined" || fixedSidebar) {
      $(this).theiaStickySidebar({ containerSelector: "#center-container > .outer-container", additionalMarginTop: 10, additionalMarginBottom: 10 });
    }
  });
  $(".blog-pager-ok .load-more").each(function () {
    var btn = $(this), wrap = btn.parent(), loader = wrap.find(".loader"), none = wrap.find(".no-more");
    btn.on("click", function () {
      $.ajax({
        type: "get",
        url: btn.attr("href"),
        beforeSend: function () { loader.show(); btn.hide(); },
        success: function (page) {
          var next = $(page).find(".blog-pager .blog-pager-older-link").attr("href");
          $("#Blog1 .grid-posts").append($(page).find("#Blog1 .grid-posts").html());
          loader.hide();
          next ? btn.attr("href", next).show() : none.show();
        },
        error: function () { loader.hide(); btn.show(); },
        complete: function () { $("#Blog1 .snip-thumbnail:not(.lazy-img)").lazyimg(); }
      });
      return false;
    });
  });
})(jQuery);
